WITH filtered AS (SELECT *, CAST(duration_sec AS DOUBLE) AS duration_sec_str FROM web_events WHERE event_time > TO_DATE('2023-07-06') AND page IS NOT NULL AND duration_sec = 166), gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM filtered), sessions_web_events AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT event_type, burst_id, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count, SUM(CASE WHEN page = '/cart' THEN duration_sec ELSE 0 END) AS cart_duration_sec, BIT_AND(duration_sec) AS duration_sec_bit_and, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes FROM sessions_web_events GROUP BY event_type, burst_id ORDER BY event_type DESC NULLS FIRST
